// This script reads input from standard input, processes it
// according to a specific mathematical function, and then
// prints results to standard output.
// It is designed to solve a problem involving counting occurrences
// of numbers generated by a quadratic form.

// First, we import the 'fs' (file system) module
// to handle file operations, specifically reading from /dev/stdin.
const      input     =      require (    "fs"    ) .  readFileSync (  "/dev/stdin"  ,   "utf8"   )

; /* End of input reading statement. */


// This is an Immediately Invoked Function Expression (IIFE).
// It encapsulates the main logic of the program.
;  (    (     inputArgument   )    =>    {

    // Split the entire input string into an array of lines
    // based on the newline character.
    const   lines    =    inputArgument   .   split (   '\n'   )
    ; // Separator for clarity

    // Extract the first line, which represents the maximum value N.
    // The `- 0` is a common JavaScript idiom to explicitly convert
    // a string to a number.
    const      N      =     lines[  0  ]      -     0
    ; /* N has been parsed from the input */


    // Define the core mathematical function 'f(x, y, z)'.
    // This function calculates a specific quadratic expression.
    // The expression is x^2 + y^2 + z^2 + xy + yz + xz.
    const     f     =     (    x    ,     y    ,     z    )     =>     {

        return     x    *    x     +     y    *    y     +     z    *    z     +     x    *    y     +     y    *    z     +     x    *    z

    } /* End of function definition for 'f' */

    ; // Another separator for visual distinction.


    // Initialize an array 'map' of size N + 1 with all zeros.
    // This array will be used to store the frequency counts
    // of the numbers generated by the function 'f'.
    // The size N + 1 is chosen because array indices are 0-based
    // and we need to store counts up to N.
    const      map      =     Array (     N     +     1     )     .     fill (     0     )
    ; /* 'map' array initialized. */


    // Begin a triple nested loop structure to iterate through
    // all possible combinations of i, j, and k from 1 up to N.
    // These loops simulate the generation of x, y, z values for the function 'f'.
    for    (    let     i     =     1     ;     i     <=     N     ;     i     ++    )     {

        for    (    let     j     =     1     ;     j     <=     N     ;     j     ++    )     {

            for    (    let     k     =     1     ;     k     <=     N     ;     k     ++    )     {

                // Calculate the value 'n' using the function 'f'
                // with the current loop variables i, j, and k.
                const      n      =     f     (     i     ,     j     ,     k     )
                ; // Value 'n' computed.

                // Check if the calculated value 'n' is within the
                // valid range (i.e., not exceeding N).
                if     (     n     <=     N     )       {

                    // If 'n' is within range, increment its count
                    // in the 'map' array.
                    map [     n     ]     ++
                }

                // If 'n' exceeds N, it means that for the current i and j,
                // any further increase in k will also result in n > N
                // (since f is monotonically increasing with its arguments).
                // Therefore, we can break out of the innermost loop
                // to optimize performance.
                else     {

                    break
                }

            } /* End of innermost loop (k) */

        } /* End of middle loop (j) */

    } /* End of outermost loop (i) */


    // Remove the first element of the 'map' array.
    // This is typically done because the problem constraints or
    // indexing might start from 1, making the 0th index irrelevant.
    // In this case, `map[0]` would always be 0 as i,j,k start from 1.
    map     .     shift (    )
    ; // First element discarded.


    // Iterate over the remaining elements of the 'map' array.
    // For each element (which represents a frequency count),
    // print it to the console.
    map     .     forEach (     n     =>     {

        console     .     log (     n     )

    }    )
    ; /* All counts have been logged. */

}    )    (    input    )
; /* End of IIFE execution. */